import{_ as n,a0 as p,w as o,s as b,I as a,x as i,a1 as e,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Ubuntu 上安裝 GitLab | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上安裝 GitLab | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上安裝 GitLab | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上安裝 GitLab | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04","title":"如何在 Ubuntu 上安裝 GitLab","tag":"202308","desc":""},"relativePath":"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04.md","filePath":"[post].md"}'),h={name:"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04.md"};function g(r,t,u,c,k,f){const s=p("Link");return o(),b("div",null,[t[18]||(t[18]=a("h1",{id:"如何在-ubuntu-上安裝-gitlab",tabindex:"-1"},[i("如何在 Ubuntu 上安裝 GitLab "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-上安裝-gitlab","aria-label":"Permalink to “如何在 Ubuntu 上安裝 GitLab”"},"​")],-1)),t[19]||(t[19]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/08/113049el2dx242c4mwm40k.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=i("GitLab 是一個開源平台，提供了強大且功能豐富的解決方案，用於管理倉庫、問題、CI/CD 管道等。如果你是 Ubuntu 22.04 或 20.04 用户，並且想要設置自己的 ",-1)),e(s,{href:"https://about.gitlab.com/"},{default:l(()=>[...t[0]||(t[0]=[i("GitLab",-1)])]),_:1}),t[2]||(t[2]=i(" 實例來簡化你的 DevOps 工作流程，那麼你來對地方了。",-1))]),t[20]||(t[20]=d(`<p>本分步指南將引導你完成 Ubuntu 22.04 或 20.04 上 GitLab 的安裝過程。GItlab 提供企業版（Gitlab EE）和社區版（Gitlab CE）。在這篇文章中，我們將介紹社區版。</p><p>先決條件：</p><ul><li>運行 Ubuntu 22.04 或 20.04 且具有 SSH 訪問權限的虛擬或專用服務器。</li><li>靜態主機名（<code>gitlab.linuxtechi.net</code>）</li><li>具有管理員權限的 Sudo 用户</li><li>2GB 內存或更多</li><li>2 個或更多 vCPU</li><li>互聯網連接</li></ul><h3 id="_1、更新系統包" tabindex="-1">1、更新系統包 <a class="header-anchor" href="#_1、更新系統包" aria-label="Permalink to “1、更新系統包”">​</a></h3><p>讓我們首先更新軟件包列表並將任何現有軟件包升級到最新版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt upgrade -y</span></span></code></pre></div><p>應用更新後重新啓動系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="_2、安裝依賴項" tabindex="-1">2、安裝依賴項 <a class="header-anchor" href="#_2、安裝依賴項" aria-label="Permalink to “2、安裝依賴項”">​</a></h3><p>GitLab 需要一些依賴項才能正常運行。使用以下命令安裝它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y curl openssh-server ca-certificates postfix</span></span></code></pre></div><p>在 postfix 安裝過程中，會出現一個配置窗口。選擇 “Internet Site”並輸入服務器的主機名作為郵件服務器名稱。這將允許 GitLab 發送電子郵件通知。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Choose-Internet-Site-Postfix-Gitlab-Installation-Ubuntu.png" alt=""></p><p>選擇 “Internet Site”，然後選擇 “OK”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/System-Hostname-Postfix-Gitlab-Ubuntu.png" alt=""></p><p>檢查系統的主機名並選擇 “OK”。</p><h3 id="_3、添加-gitlab-apt-存儲庫" tabindex="-1">3、添加 GitLab Apt 存儲庫 <a class="header-anchor" href="#_3、添加-gitlab-apt-存儲庫" aria-label="Permalink to “3、添加 GitLab Apt 存儲庫”">​</a></h3><p>現在，我們將添加 GitLab 倉庫，運行以下 <code>curl</code> 命令。它將自動檢測你的 Ubuntu 版本並相應地設置倉庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -sS https://packages.gitlab.com/install/repositories/gitlab/gitlab-ce/script.deb.sh | sudo bash</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Add-GitLAb-CE-Apt-Repository-Ubuntu.png" alt=""></p><h3 id="_4、安裝-gitlab" tabindex="-1">4、安裝 Gitlab <a class="header-anchor" href="#_4、安裝-gitlab" aria-label="Permalink to “4、安裝 Gitlab”">​</a></h3><p>運行以下命令在你的 ubuntu 系統上自動安裝和配置 gitlab-ce，將服務器的主機名替換為你的設置，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo EXTERNAL_URL=&quot;http://gitlab.linuxtechi.net&quot; apt install gitlab-ce</span></span></code></pre></div><p>上述命令成功執行後，我們將得到如下輸出。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Apt-Install-Gitlab-ce-Ubuntu.png" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-Successful-Installlation-Message-Ubuntu.png" alt=""></p><p>上面的輸出確認 GitLab 已成功安裝。gitlab web 界面的用户名是 root，密碼存儲在 <code>/etc/gitlab/initial_root_password</code>。</p><p>注意：如果你的 ubuntu 系統上啓用了操作系統防火牆，那請允許 80 和 443 端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow http</span></span>
<span class="line"><span>$ sudo ufw allow https</span></span></code></pre></div><h3 id="_5、訪問-gitlab-web-界面" tabindex="-1">5、訪問 GitLab Web 界面 <a class="header-anchor" href="#_5、訪問-gitlab-web-界面" aria-label="Permalink to “5、訪問 GitLab Web 界面”">​</a></h3><p>安裝並配置 GitLab 後，打開 Web 瀏覽器並輸入服務器的 IP 地址或主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://&lt;Server-IP-Address-or-Hostname&gt;</span></span></code></pre></div><ul><li>用户名：<code>root</code></li><li>密碼：從 <code>/etc/gitlab/initial_root_password</code> 獲取密碼</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/GitLab-Login-Page-Post-Installation-Ubuntu.png" alt=""></p><p>點擊“<ruby>登錄<rt>Sign in</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/GitLab-Web-Interface-Ubuntu.png" alt=""></p><p>很好，上面確認我們已經成功登錄 Gitlab Web 界面。</p><p>目前我們的 GitLab 服務器運行在 http（80）協議上，如果你想為你的 GitLab 啓用 https，請參考以下步驟。</p><h3 id="_6、為-gitlab-web-界面設置-https" tabindex="-1">6、為 GitLab Web 界面設置 HTTPS <a class="header-anchor" href="#_6、為-gitlab-web-界面設置-https" aria-label="Permalink to “6、為 GitLab Web 界面設置 HTTPS”">​</a></h3><p>為提高安全性，可使用自簽名證書或 Let&#39;s Encrypt 為 GitLab 實例配置 HTTPS。Let&#39;s Encrypt 只適用於互聯網上有 A 記錄的公有域。但在本例中，我們使用的是私有域，因此將使用自簽名證書來確保 GitLab 的安全。</p><p>現在，讓我們創建以下文件夾並使用 <code>openssl</code> 命令生成自簽名證書：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /etc/gitlab/ssl</span></span>
<span class="line"><span>$ sudo chmod 755 /etc/gitlab/ssl</span></span></code></pre></div><p>使用以下 <code>openssl</code> 命令生成私鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl genrsa -des3 -out /etc/gitlab/ssl/gitlab.linuxtechi.net.key 2048</span></span></code></pre></div><p>輸入密碼並記住它。</p><p>使用以下命令創建 CSR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl req -new -key /etc/gitlab/ssl/gitlab.linuxtechi.net.key -out /etc/gitlab/ssl/gitlab.linuxtechi.net.csr</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Generate-CSR-Self-Sign-Cert-Gitlab.png" alt=""></p><p>從密鑰中刪除密碼串，依次執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp -v /etc/gitlab/ssl/gitlab.linuxtechi.net.{key,original}</span></span>
<span class="line"><span>$ sudo openssl rsa -in /etc/gitlab/ssl/gitlab.linuxtechi.net.original -out /etc/gitlab/ssl/gitlab.linuxtechi.net.key</span></span>
<span class="line"><span>$ sudo rm -v /etc/gitlab/ssl/gitlab.linuxtechi.net.original</span></span></code></pre></div><p>創建證書文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl x509 -req -days 1460 -in /etc/gitlab/ssl/gitlab.linuxtechi.net.csr -signkey /etc/gitlab/ssl/gitlab.linuxtechi.net.key -out /etc/gitlab/ssl/gitlab.linuxtechi.net.crt</span></span></code></pre></div><p>使用下面的 <code>rm</code> 命令刪除 CSR 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm -v /etc/gitlab/ssl/gitlab.linuxtechi.net.csr</span></span></code></pre></div><p>設置密鑰和證書文件的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /etc/gitlab/ssl/gitlab.linuxtechi.net.key</span></span>
<span class="line"><span>$ sudo chmod 600 /etc/gitlab/ssl/gitlab.linuxtechi.net.crt</span></span></code></pre></div><p>Gitlab 服務器的所有重要配置均由文件 <code>/etc/gitlab/gitlab.rb</code> 控制，因此編輯此文件，搜索 <code>external_url</code> 並添加 <code>https://gitlab.linuxtechi.net</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/gitlab/gitlab.rb</span></span>
<span class="line"><span>----------------------------------------------------------</span></span>
<span class="line"><span>external_url &#39;https://gitlab.linuxtechi.net&#39;</span></span>
<span class="line"><span>----------------------------------------------------------</span></span></code></pre></div><p>保存並退出文件，使用下面的命令重新配置 gitlab，以便其 Web 界面可以使用 HTTPS。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo gitlab-ctl reconfigure</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-reconfigured-Ubuntu.png" alt=""></p><p>成功執行上述命令後，你的 GitLab 界面應該可以通過 HTTPS 協議訪問，在我的例子中，URL 為：<code>https://gitlab.linuxtechi.net/</code></p><p>當你第一次訪問它時，它會説你的連接不安全，點擊“接受風險並繼續”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-Web-Interface-over-Https-Ubuntu.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>恭喜！ 你已在 Ubuntu 22.04 或 20.04 系統上成功安裝 GitLab。隨着 GitLab 的啓動和運行，你現在可以創建倉庫，與你的團隊協作，並通過 GitLab 令人印象深刻的功能增強你的開發工作流程。享受無縫版本控制、持續集成等，一切盡在你的掌控之中！</p><p><em>（題圖：MJ/c6a3e27e-fe58-4184-b133-9e9c67224316）</em></p><hr>`,68)),a("p",null,[t[4]||(t[4]=i("via: ",-1)),e(s,{href:"https://www.linuxtechi.com/how-to-install-gitlab-on-ubuntu/"},{default:l(()=>[...t[3]||(t[3]=[i("https://www.linuxtechi.com/how-to-install-gitlab-on-ubuntu/",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=i("作者：",-1)),e(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[5]||(t[5]=[i("Pradeep Kumar",-1)])]),_:1}),t[10]||(t[10]=i(" 選題：",-1)),e(s,{href:"https://github.com/lkxed/"},{default:l(()=>[...t[6]||(t[6]=[i("lkxed",-1)])]),_:1}),t[11]||(t[11]=i(" 譯者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[7]||(t[7]=[i("geekpi",-1)])]),_:1}),t[12]||(t[12]=i(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[i("LCTT",-1)])]),_:1}),t[16]||(t[16]=i(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[i("Linux中國",-1)])]),_:1}),t[17]||(t[17]=i(" 榮譽推出",-1))])])}const y=n(h,[["render",g]]);export{w as __pageData,y as default};
